use std::iter::Peekable;

use kurbo::BezPath;

use crate::{
    curve::AlmostHorizontalDecomposition,
    geom::{Point, Segment, monotonic_pieces},
    num::CheapOrderedFloat,
};

/// An index into our segment arena.
///
/// Throughout this library, we assign identities to segments, so that we may
/// consider segments as different even if they have the same start- and end-points.
///
/// This index is used to identify a segment, whose data can be retrieved by looking
/// it up in [`Segments`]. (Of course, this index-as-identifier breaks down if there are
/// multiple `Segments` in flight. Just be careful not to mix them up.)
#[cfg_attr(test, derive(serde::Serialize))]
#[derive(Clone, Copy, PartialOrd, Ord, PartialEq, Eq, Hash)]
pub struct SegIdx(pub(crate) usize);

/// A vector indexed by `SegIdx`.
#[cfg_attr(test, derive(serde::Serialize))]
#[derive(Clone, Hash, PartialEq, Eq)]
#[cfg_attr(test, serde(transparent))]
pub struct SegVec<T> {
    inner: Vec<T>,
}

impl_typed_vec!(SegVec, SegIdx, "s");

/// An arena of segments, each of which is a cubic Bézier.
///
/// Segments are indexed by [`SegIdx`] and can be retrieved by indexing (i.e. with square brackets).
#[derive(Clone, Default)]
pub struct Segments {
    segs: SegVec<Segment>,
    horizontal_decomps: SegVec<AlmostHorizontalDecomposition>,
    contour_prev: SegVec<Option<SegIdx>>,
    contour_next: SegVec<Option<SegIdx>>,
    /// For each segment, stores true if the sweep-line order (small y to big y)
    /// is the same as the orientation in its original contour.
    orientation: SegVec<bool>,
    /// For each segment, stores its parameter range in the original input
    /// segment (which may have been split into monotonic sub-segments). Keeping
    /// track of where the splits happened allows us to potentially merge things
    /// back at the end.
    pub(crate) split_from_predecessor: SegVec<(f64, f64)>,
    /// The original input segments, for reconstructing/merging. (TODO: this
    /// representation is wasteful, since we only need it for segments that
    /// got split.)
    pub(crate) input_segs: SegVec<kurbo::PathSeg>,

    /// All the entrance heights, of segments, ordered by height.
    /// This includes horizontal segments.
    enter: Vec<(f64, SegIdx)>,
    /// All the exit heights of segments, ordered by height.
    /// This does not include horizontal segments.
    exit: Vec<(f64, SegIdx)>,
}

/// Certain operations expect closed paths, and return this as an error when a path is not closed.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NonClosedPath {
    /// The point at the start of the non-closed path (always generated by a [`kurbo::PathEl::MoveTo`]).
    pub start_point: kurbo::Point,
    /// The point at the end of the non-closed path.
    pub end_point: kurbo::Point,
}

impl std::fmt::Display for NonClosedPath {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "non-closed path starting at {} and ending at {}",
            self.start_point, self.end_point,
        )
    }
}

impl std::error::Error for NonClosedPath {}

struct SegmentEntryFormatter<'a> {
    idx: SegIdx,
    seg: &'a Segment,
    prev: Option<SegIdx>,
    next: Option<SegIdx>,
    oriented: bool,
}

impl std::fmt::Debug for SegmentEntryFormatter<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let seg_idx = self.idx;
        let seg = self.seg;
        let prefix = if self.oriented {
            self.prev.map(|i| format!("{i:?} -> ")).unwrap_or_default()
        } else {
            self.next.map(|i| format!("{i:?} <- ")).unwrap_or_default()
        };
        let suffix = if self.oriented {
            self.next.map(|i| format!(" -> {i:?}")).unwrap_or_default()
        } else {
            self.prev.map(|i| format!(" <- {i:?}")).unwrap_or_default()
        };
        write!(f, "{seg_idx:?}: {prefix}{seg:?}{suffix}")
    }
}

impl std::fmt::Debug for Segments {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let mut list = f.debug_list();
        for (idx, seg) in self.segs.iter() {
            list.entry(&SegmentEntryFormatter {
                idx,
                seg,
                prev: self.contour_prev[idx],
                next: self.contour_next[idx],
                oriented: self.orientation[idx],
            });
        }
        list.finish()
    }
}

fn cyclic_pairs<T>(xs: &[T]) -> impl Iterator<Item = (&T, &T)> {
    pairs(xs).chain(xs.last().zip(xs.first()))
}

fn pairs<T>(xs: &[T]) -> impl Iterator<Item = (&T, &T)> {
    xs.windows(2).map(|pair| (&pair[0], &pair[1]))
}

// Craft patch (batch paths): counts calls to `enter_order` in tests.
#[cfg(test)]
thread_local! {
    static ENTER_COMPARISONS: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
}

// Craft patch (batch paths): the order of `Segments::enter`, by entrance
// height and then by horizontal position at that height.
fn enter_order(
    segs: &SegVec<Segment>,
    (y1, seg1): &(f64, SegIdx),
    (y2, seg2): &(f64, SegIdx),
) -> std::cmp::Ordering {
    #[cfg(test)]
    ENTER_COMPARISONS.with(|c| c.set(c.get() + 1));
    CheapOrderedFloat::from(*y1)
        .cmp(&CheapOrderedFloat::from(*y2))
        .then_with(|| {
            CheapOrderedFloat::from(segs[*seg1].at_y(*y1))
                .cmp(&CheapOrderedFloat::from(segs[*seg2].at_y(*y1)))
        })
}

// Craft patch (batch paths): sorts `v[old_len..]` and merges it into
// `v[..old_len]`, which must already be sorted by `cmp`. The result is the
// order a stable sort of all of `v` gives: on a tie, an entry from before
// `old_len` comes first. Only the part of the sorted prefix that the new
// entries reach is moved, so entries added below every existing one cost a
// sort of the new entries and a binary search.
fn merge_sorted_tail<T: Copy>(
    v: &mut Vec<T>,
    old_len: usize,
    mut cmp: impl FnMut(&T, &T) -> std::cmp::Ordering,
) {
    let mut tail = v.split_off(old_len);
    tail.sort_by(&mut cmp);
    let Some(first) = tail.first() else {
        return;
    };
    let pos = v.partition_point(|e| cmp(e, first) != std::cmp::Ordering::Greater);
    if pos == v.len() {
        v.append(&mut tail);
        return;
    }
    let suffix = v.split_off(pos);
    v.reserve(suffix.len() + tail.len());
    let (mut i, mut j) = (0, 0);
    while i < suffix.len() && j < tail.len() {
        if cmp(&tail[j], &suffix[i]) == std::cmp::Ordering::Less {
            v.push(tail[j]);
            j += 1;
        } else {
            v.push(suffix[i]);
            i += 1;
        }
    }
    v.extend_from_slice(&suffix[i..]);
    v.extend_from_slice(&tail[j..]);
}

struct SubpathIter<'a, I: Iterator> {
    inner: &'a mut Peekable<I>,
    started: bool,
}

impl<I> Iterator for SubpathIter<'_, I>
where
    I: Iterator<Item = kurbo::PathEl>,
{
    type Item = kurbo::PathEl;

    fn next(&mut self) -> Option<Self::Item> {
        let ret = self.inner.peek()?;
        if matches!(ret, kurbo::PathEl::MoveTo(_)) && self.started {
            None
        } else {
            self.started = true;
            self.inner.next()
        }
    }
}

struct Subpaths<I: Iterator> {
    inner: Peekable<I>,
}

impl<I> Subpaths<I>
where
    I: Iterator<Item = kurbo::PathEl>,
{
    fn next(&mut self) -> Option<SubpathIter<'_, I>> {
        if self.inner.peek().is_none() {
            None
        } else {
            Some(SubpathIter {
                inner: &mut self.inner,
                started: false,
            })
        }
    }
}

impl Segments {
    /// The number of segments in this arena.
    #[allow(clippy::len_without_is_empty)]
    pub fn len(&self) -> usize {
        self.segs.len()
    }

    /// Iterate over all indices that can be used to index into this arena.
    pub fn indices(&self) -> impl Iterator<Item = SegIdx> + use<> {
        (0..self.segs.len()).map(SegIdx)
    }

    /// Iterate over all segments in this arena.
    pub fn segments(&self) -> impl Iterator<Item = &Segment> {
        self.segs.iter().map(|(_, s)| s)
    }

    /// Returns the starting point of the segment at `idx`, relative to the segment's original orientation.
    ///
    /// The segment itself is stored in sweep-line order (i.e. its starting
    /// point has the smaller y coordinate) regardless of the original
    /// orientation of the segment. Use this method to retrieve the segment's
    /// original start point.
    pub fn oriented_start(&self, idx: SegIdx) -> Point {
        if self.orientation[idx] {
            self[idx].start()
        } else {
            self[idx].end()
        }
    }

    /// Returns the ending point of the segment at `idx`, relative to the segment's original orientation.
    ///
    /// The segment itself is stored in sweep-line order (i.e. its starting
    /// point has the smaller y coordinate) regardless of the original
    /// orientation of the segment. Use this method to retrieve the segment's
    /// original end point.
    pub fn oriented_end(&self, idx: SegIdx) -> Point {
        if self.orientation[idx] {
            self[idx].end()
        } else {
            self[idx].start()
        }
    }

    /// Returns the index of the segment following `idx`.
    ///
    /// If `idx` is part of a non-closed path and it is the last segment,
    /// this returns `None`. If `idx` is part of a closed path, this will
    /// always return `Some`, and you might need to be careful to avoid looping
    /// infinitely.
    pub fn contour_next(&self, idx: SegIdx) -> Option<SegIdx> {
        self.contour_next[idx]
    }

    /// Returns the index of the segment preceding `idx`.
    ///
    /// If `idx` is part of a non-closed path and it is the first segment,
    /// this returns `None`. If `idx` is part of a closed path, this will
    /// always return `Some`, and you might need to be careful to avoid looping
    /// infinitely.
    pub fn contour_prev(&self, idx: SegIdx) -> Option<SegIdx> {
        self.contour_prev[idx]
    }

    /// Does the sweep-line orientation of `idx` agree with its original orientation?
    pub fn positively_oriented(&self, idx: SegIdx) -> bool {
        self.orientation[idx]
    }

    /// Add a (non-closed) polyline to this arena.
    pub fn add_points<P: Into<Point>>(&mut self, ps: impl IntoIterator<Item = P>) {
        let old_len = self.segs.len();

        let ps: Vec<_> = ps.into_iter().map(|p| p.into()).collect();
        if ps.len() <= 1 {
            return;
        }

        for (p, q) in pairs(&ps) {
            let (a, b, orient) = if p < q { (p, q, true) } else { (q, p, false) };
            self.push_seg(Segment::straight(*a, *b));
            self.orientation.push(orient);
            self.split_from_predecessor.push((0.0, 1.0));
            self.input_segs
                .push(kurbo::PathSeg::Line((p.to_kurbo(), q.to_kurbo()).into()));
            self.contour_prev
                .push(Some(SegIdx(self.segs.len().saturating_sub(2))));
            self.contour_next.push(Some(SegIdx(self.segs.len())));
        }

        if old_len < self.segs.len() {
            self.contour_prev[SegIdx(old_len)] = None;
            // unwrap: contour_next has the same length as `segs`, which is
            // non-empty because we checked its length
            *self.contour_next.inner.last_mut().unwrap() = None;
        }

        self.update_enter_exit(old_len);
    }

    /// Add a collection of closed polylines to this arena.
    ///
    /// This can be much faster than calling `add_cycles` repeatedly.
    pub fn add_closed_polylines<P: Into<Point>>(
        &mut self,
        ps: impl IntoIterator<Item = impl IntoIterator<Item = P>>,
    ) {
        let old_len = self.segs.len();
        for p in ps {
            self.add_polyline_without_updating_enter_exit(p);
        }
        self.update_enter_exit(old_len);
    }

    /// Add a closed polyline to this arena.
    pub fn add_closed_polyline<P: Into<Point>>(&mut self, ps: impl IntoIterator<Item = P>) {
        let old_len = self.segs.len();
        self.add_polyline_without_updating_enter_exit(ps);
        self.update_enter_exit(old_len);
    }

    /// Add a Bézier path to this arena.
    ///
    /// The path can contain multiple subpaths, and each of them must be closed.
    ///
    /// Each call merges the path's entrances and exits into the sorted ones
    /// already in the arena, which moves every existing entry that sorts after
    /// them. To add many paths, call [`Segments::add_bez_paths`] once instead.
    pub fn add_bez_path(&mut self, p: &BezPath) -> Result<(), NonClosedPath> {
        let old_len = self.segs.len();
        self.add_path_without_updating_enter_exit(p, true)?;
        self.update_enter_exit(old_len);
        Ok(())
    }

    /// Add a Bézier path to this arena.
    ///
    /// The path can contain multiple subpaths, and each of them may or may not be closed.
    ///
    /// Each call merges the path's entrances and exits into the sorted ones
    /// already in the arena, which moves every existing entry that sorts after
    /// them. To add many paths, call [`Segments::add_non_closed_bez_paths`]
    /// once instead.
    pub fn add_non_closed_bez_path(&mut self, p: &BezPath) -> Result<(), NonClosedPath> {
        let old_len = self.segs.len();
        self.add_path_without_updating_enter_exit(p, false)?;
        self.update_enter_exit(old_len);
        Ok(())
    }

    // Craft patch (batch paths): add every path, then sort the entrances and exits once.
    /// Add a collection of Bézier paths to this arena.
    ///
    /// Every subpath must be closed. When every path is closed, this gives the
    /// same arena as calling [`Segments::add_bez_path`] on each path in turn,
    /// and it sorts the entrances and exits once instead of once per path.
    ///
    /// If a subpath is not closed, this returns the error for the first such
    /// subpath. The paths before the one holding it stay in the arena, and no
    /// segment of that path or of any later path is added.
    pub fn add_bez_paths<'a>(
        &mut self,
        ps: impl IntoIterator<Item = &'a BezPath>,
    ) -> Result<(), NonClosedPath> {
        self.add_paths_updating_enter_exit_once(ps, true)
    }

    // Craft patch (batch paths).
    /// Add a collection of Bézier paths to this arena.
    ///
    /// Each subpath may or may not be closed. This gives the same arena as
    /// calling [`Segments::add_non_closed_bez_path`] on each path in turn, and
    /// it sorts the entrances and exits once instead of once per path.
    pub fn add_non_closed_bez_paths<'a>(
        &mut self,
        ps: impl IntoIterator<Item = &'a BezPath>,
    ) -> Result<(), NonClosedPath> {
        self.add_paths_updating_enter_exit_once(ps, false)
    }

    // Craft patch (batch paths).
    fn add_paths_updating_enter_exit_once<'a>(
        &mut self,
        ps: impl IntoIterator<Item = &'a BezPath>,
        must_be_closed: bool,
    ) -> Result<(), NonClosedPath> {
        let old_len = self.segs.len();
        let mut result = Ok(());
        for p in ps {
            let path_start = self.segs.len();
            result = self.add_path_without_updating_enter_exit(p, must_be_closed);
            if result.is_err() {
                // The failing path's segments are removed, so none is left
                // linked to an index past the end of the arena.
                self.truncate_unentered(path_start);
                break;
            }
        }
        self.update_enter_exit(old_len);
        result
    }

    // Craft patch (batch paths): drops every segment at index `len` or above.
    // `enter` and `exit` are left alone, so this is only for segments that
    // `update_enter_exit` has not seen yet.
    fn truncate_unentered(&mut self, len: usize) {
        self.segs.inner.truncate(len);
        self.horizontal_decomps.inner.truncate(len);
        self.contour_prev.inner.truncate(len);
        self.contour_next.inner.truncate(len);
        self.orientation.inner.truncate(len);
        self.split_from_predecessor.inner.truncate(len);
        self.input_segs.inner.truncate(len);
    }

    pub(crate) fn add_path_without_updating_enter_exit(
        &mut self,
        p: &BezPath,
        must_be_closed: bool,
    ) -> Result<(), NonClosedPath> {
        let mut subpaths = Subpaths {
            inner: p.iter().peekable(),
        };
        while let Some(subpath) = subpaths.next() {
            let old_len = self.segs.len();
            for seg in kurbo::segments(subpath) {
                let pieces = monotonic_pieces(seg);
                for monotonic in pieces {
                    self.push_seg(monotonic.piece);
                    self.orientation.push(monotonic.positively_oriented);
                    self.split_from_predecessor
                        .push((monotonic.start_t, monotonic.end_t));
                    self.input_segs.push(seg);
                    self.contour_prev
                        .push(Some(SegIdx(self.segs.len().saturating_sub(2))));
                    self.contour_next.push(Some(SegIdx(self.segs.len())));
                }
            }
            if old_len < self.segs.len() {
                let start_idx = SegIdx(old_len);
                let end_idx = SegIdx(self.segs.len() - 1);

                // unwrap: contour_next has the same length as `segs`, which is
                // non-empty because we checked its length
                let start_point = self.oriented_start(start_idx).to_kurbo();
                let end_point = self.oriented_end(end_idx).to_kurbo();
                if start_point == end_point {
                    self.contour_prev[start_idx] = Some(end_idx);
                    self.contour_next[end_idx] = Some(start_idx);
                } else if must_be_closed {
                    return Err(NonClosedPath {
                        start_point,
                        end_point,
                    });
                } else {
                    self.contour_prev[start_idx] = None;
                    self.contour_next[end_idx] = None;
                }
            }
        }
        Ok(())
    }

    fn add_polyline_without_updating_enter_exit<P: Into<Point>>(
        &mut self,
        ps: impl IntoIterator<Item = P>,
    ) {
        let old_len = self.segs.len();

        let ps: Vec<_> = ps.into_iter().map(|p| p.into()).collect();
        if ps.len() <= 1 {
            return;
        }

        for (p, q) in cyclic_pairs(&ps) {
            if p == q {
                continue;
            }
            let (a, b, orient) = if p < q { (p, q, true) } else { (q, p, false) };
            self.push_seg(Segment::straight(*a, *b));
            self.orientation.push(orient);
            self.split_from_predecessor.push((0.0, 1.0));
            self.input_segs
                .push(kurbo::PathSeg::Line((p.to_kurbo(), q.to_kurbo()).into()));
            self.contour_prev
                .push(Some(SegIdx(self.segs.len().saturating_sub(2))));
            self.contour_next.push(Some(SegIdx(self.segs.len())));
        }

        if old_len < self.segs.len() {
            self.contour_prev[SegIdx(old_len)] = Some(SegIdx(self.segs.len() - 1));
            // unwrap: contour_next has the same length as `segs`, which is
            // non-empty because we checked its length
            *self.contour_next.inner.last_mut().unwrap() = Some(SegIdx(old_len));
        }
    }

    fn push_seg(&mut self, seg: Segment) {
        let decomp = if seg.is_horizontal() {
            AlmostHorizontalDecomposition::default()
        } else {
            AlmostHorizontalDecomposition::from_monotone_cubic(seg.to_kurbo_cubic())
        };
        self.horizontal_decomps.push(decomp);
        self.segs.push(seg);
    }

    /// Construct a segment arena from a single closed polyline.
    pub fn from_closed_polyline<P: Into<Point>>(ps: impl IntoIterator<Item = P>) -> Self {
        let mut ret = Self::default();
        ret.add_closed_polyline(ps);
        ret
    }

    pub(crate) fn update_enter_exit(&mut self, old_len: usize) {
        // Craft patch (batch paths).
        let enter_old_len = self.enter.len();
        let exit_old_len = self.exit.len();
        for idx in old_len..self.len() {
            let seg_idx = SegIdx(idx);
            let seg = &self.segs[seg_idx];

            self.enter.push((seg.start().y, seg_idx));
            if !seg.is_horizontal() {
                self.exit.push((seg.end().y, seg_idx));
            }
        }

        // We sort the enter segments by y position, and then by horizontal
        // start position so that they're fairly likely to get inserted in the
        // sweep-line in order (which makes the indexing fix-ups faster).
        //
        // Craft patch (batch paths): the entries before `old_len` are already
        // sorted, so only the new entries are sorted and then merged in. This
        // gives the same order as a stable sort of the whole vector.
        let segs = &self.segs;
        merge_sorted_tail(&mut self.enter, enter_old_len, |a, b| {
            enter_order(segs, a, b)
        });
        merge_sorted_tail(&mut self.exit, exit_old_len, |(y1, _), (y2, _)| {
            CheapOrderedFloat::from(*y1).cmp(&CheapOrderedFloat::from(*y2))
        });
    }

    /// All the entrance heights of segments, ordered by height.
    ///
    /// Includes horizontal segments.
    pub fn entrances(&self) -> &[(f64, SegIdx)] {
        &self.enter
    }

    /// All the exit heights of segments, ordered by height.
    ///
    /// Does not include horizontal segments.
    pub fn exits(&self) -> &[(f64, SegIdx)] {
        &self.exit
    }

    /// Checks that we satisfy our internal invariants. For testing only.
    pub fn check_invariants(&self) {
        for (idx, seg) in self.segs.iter() {
            assert!(seg.start() <= seg.end());
            assert_ne!(seg.start(), seg.end());
            if let Some(next_idx) = self.contour_next(idx) {
                assert_eq!(self.oriented_end(idx), self.oriented_start(next_idx));
                assert_eq!(self.contour_prev(next_idx), Some(idx));
            }
        }
    }

    pub(crate) fn horiz_decomp(&self, idx: SegIdx) -> &AlmostHorizontalDecomposition {
        debug_assert!(!self.segs[idx].is_horizontal());
        &self.horizontal_decomps[idx]
    }
}

impl std::ops::Index<SegIdx> for Segments {
    type Output = Segment;

    fn index(&self, index: SegIdx) -> &Self::Output {
        &self.segs[index]
    }
}

// Craft patch (batch paths).
#[cfg(test)]
mod tests {
    use kurbo::BezPath;

    use super::{SegIdx, Segments};
    use crate::num::CheapOrderedFloat;

    // Paths on a small integer grid, so that many segments share entrance
    // heights and entrance positions, with lines, quadratics and cubics.
    fn grid_paths(count: usize, closed: bool) -> Vec<BezPath> {
        let mut state: u64 = 0x2545_f491_4f6c_dd1d;
        let mut next = move || {
            state = state
                .wrapping_mul(6_364_136_223_846_793_005)
                .wrapping_add(1_442_695_040_888_963_407);
            ((state >> 33) % 12) as f64
        };
        (0..count)
            .map(|i| {
                let mut p = BezPath::new();
                p.move_to((next(), next()));
                match i % 3 {
                    0 => {
                        p.line_to((next(), next()));
                        p.line_to((next(), next()));
                    }
                    1 => {
                        p.quad_to((next(), next()), (next(), next()));
                        p.line_to((next(), next()));
                    }
                    _ => {
                        p.curve_to((next(), next()), (next(), next()), (next(), next()));
                    }
                }
                if closed {
                    p.close_path();
                }
                p
            })
            .collect()
    }

    fn assert_same_arena(a: &Segments, b: &Segments) {
        assert_eq!(a.segs, b.segs);
        assert_eq!(a.orientation, b.orientation);
        assert_eq!(a.contour_prev, b.contour_prev);
        assert_eq!(a.contour_next, b.contour_next);
        assert_eq!(a.enter, b.enter);
        assert_eq!(a.exit, b.exit);
    }

    #[test]
    fn add_bez_paths_matches_repeated_add_bez_path() {
        let paths = grid_paths(300, true);
        let mut one_by_one = Segments::default();
        for p in &paths {
            one_by_one.add_bez_path(p).unwrap();
        }
        let mut batch = Segments::default();
        batch.add_bez_paths(&paths).unwrap();
        batch.check_invariants();
        assert!(batch.len() > 600);
        assert_same_arena(&one_by_one, &batch);

        // A second batch adds to the arena that is already there.
        let more = grid_paths(50, true);
        for p in &more {
            one_by_one.add_bez_path(p).unwrap();
        }
        batch.add_bez_paths(&more).unwrap();
        assert_same_arena(&one_by_one, &batch);
    }

    #[test]
    fn add_non_closed_bez_paths_matches_repeated_add_non_closed_bez_path() {
        let paths = grid_paths(300, false);
        let mut one_by_one = Segments::default();
        for p in &paths {
            one_by_one.add_non_closed_bez_path(p).unwrap();
        }
        let mut batch = Segments::default();
        batch.add_non_closed_bez_paths(&paths).unwrap();
        batch.check_invariants();
        assert_same_arena(&one_by_one, &batch);
    }

    #[test]
    fn add_bez_paths_stops_at_an_open_path() {
        let mut paths = grid_paths(4, true);
        let mut open = BezPath::new();
        open.move_to((0.0, 0.0));
        open.line_to((1.0, 5.0));
        paths.insert(2, open);

        let mut segments = Segments::default();
        let err = segments.add_bez_paths(&paths).unwrap_err();
        assert_eq!(err.start_point, kurbo::Point::new(0.0, 0.0));
        assert_eq!(err.end_point, kurbo::Point::new(1.0, 5.0));

        // The two paths before the open one stay, and nothing of the open
        // path or the paths after it is added.
        segments.check_invariants();
        let mut expected = Segments::default();
        expected.add_bez_paths(&paths[..2]).unwrap();
        assert_same_arena(&expected, &segments);
        assert_eq!(segments.input_segs, expected.input_segs);
        assert_eq!(
            segments.split_from_predecessor,
            expected.split_from_predecessor
        );
    }

    type Events = Vec<(f64, SegIdx)>;

    // The entrance and exit order that sorting every entry in index order
    // gives, as `update_enter_exit` did before it merged new entries in.
    fn sorted_from_scratch(s: &Segments) -> (Events, Events) {
        let mut enter = Vec::new();
        let mut exit = Vec::new();
        for idx in s.indices() {
            let seg = &s[idx];
            enter.push((seg.start().y, idx));
            if !seg.is_horizontal() {
                exit.push((seg.end().y, idx));
            }
        }
        enter.sort_by(|a, b| super::enter_order(&s.segs, a, b));
        exit.sort_by(|(y1, _), (y2, _)| {
            CheapOrderedFloat::from(*y1).cmp(&CheapOrderedFloat::from(*y2))
        });
        (enter, exit)
    }

    #[test]
    fn merged_entrances_and_exits_match_a_full_sort() {
        // Paths added one at a time land above, below and among the ones
        // already there, with many equal heights and positions.
        let mut one_by_one = Segments::default();
        for p in &grid_paths(400, true) {
            one_by_one.add_bez_path(p).unwrap();
            let (enter, exit) = sorted_from_scratch(&one_by_one);
            assert_eq!(one_by_one.enter, enter);
            assert_eq!(one_by_one.exit, exit);
        }

        let mut batches = Segments::default();
        let paths = grid_paths(400, false);
        for chunk in paths.chunks(37) {
            batches.add_non_closed_bez_paths(chunk).unwrap();
            let (enter, exit) = sorted_from_scratch(&batches);
            assert_eq!(batches.enter, enter);
            assert_eq!(batches.exit, exit);
        }
    }

    #[test]
    fn paths_added_in_height_order_are_not_sorted_again() {
        // 2,000 triangles in rows of 400, added one at a time from the top
        // row down and left to right.
        let triangles: Vec<BezPath> = (0..2000)
            .map(|i| {
                let x = (i % 400) as f64 * 3.0;
                let y = (i / 400) as f64 * 3.0;
                let mut p = BezPath::new();
                p.move_to((x, y));
                p.line_to((x + 2.0, y));
                p.line_to((x + 1.0, y + 2.0));
                p.close_path();
                p
            })
            .collect();
        let mut segments = Segments::default();
        super::ENTER_COMPARISONS.with(|c| c.set(0));
        for p in &triangles {
            segments.add_bez_path(p).unwrap();
        }
        let comparisons = super::ENTER_COMPARISONS.with(|c| c.get());
        assert_eq!(segments.len(), 6000);
        // Sorting all the entrances on every call compares each existing
        // entrance at least once per call, about 6,000,000 comparisons here.
        assert!(
            comparisons < 64 * 6000,
            "{comparisons} entrance comparisons"
        );
        let (enter, exit) = sorted_from_scratch(&segments);
        assert_eq!(segments.enter, enter);
        assert_eq!(segments.exit, exit);
    }
}
